def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    my_last, opp_last = history[-1]
    if opp_last == 'C':
        return 'C'
    opp_def = 0
    for a, b in history:
        if b == 'D':
            opp_def += 1
    coop_rate = (n - opp_def) / n
    cons_def = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            cons_def += 1
        else:
            break
    if my_last == 'D':
        if coop_rate >= 0.5:
            if cons_def >= 2:
                return 'C' if rng.random() < 0.5 else 'D'
            else:
                return 'C' if rng.random() < 0.2 else 'D'
        return 'D'
    else:
        if n >= 2 and history[-2][0] == 'D':
            return 'C'
        return 'D'
